import { Button } from '@/components/ui/button'
import { User, LogOut, Mountain } from 'lucide-react'
import { Link } from 'react-router-dom'
import { useAuth } from '@/contexts/AuthContext'

interface AppHeaderProps {
  title?: string
  subtitle?: string
  icon?: React.ReactNode
  backTo?: string
  isDashboard?: boolean
  rightContent?: React.ReactNode
}

export function AppHeader({ 
  title = 'BetterPack',
  subtitle, 
  icon, 
  backTo = '/dashboard',
  isDashboard = false,
  rightContent 
}: AppHeaderProps) {
  const { user, signOut } = useAuth()

  return (
    <header className="bg-white border-b border-border/40 sticky top-0 z-50 backdrop-blur-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Left section - Breadcrumb-style navigation */}
          <div className="flex items-center space-x-3 flex-1 min-w-0">
            {/* BetterPack branding - always visible and clickable */}
            <Link 
              to="/dashboard" 
              className="flex items-center space-x-2 sm:space-x-3 hover:opacity-80 transition-opacity flex-shrink-0"
            >
              <div className="p-1.5 sm:p-2 bg-primary/10 rounded-lg">
                <Mountain className="h-5 w-5 sm:h-6 sm:w-6 text-primary" />
              </div>
              <h1 className="text-lg sm:text-xl font-semibold tracking-tight">BetterPack</h1>
            </Link>

            {/* Page title - shown as breadcrumb for non-dashboard pages */}
            {!isDashboard && (
              <>
                <span className="text-muted-foreground">/</span>
                <div className="flex items-center space-x-2 min-w-0">
                  {icon && (
                    <div className="p-1.5 bg-primary/10 rounded-lg flex-shrink-0">
                      {icon}
                    </div>
                  )}
                  <div className="min-w-0">
                    <h2 className="text-lg sm:text-xl font-semibold tracking-tight truncate">
                      {title}
                    </h2>
                    {subtitle && (
                      <p className="text-xs text-muted-foreground truncate hidden sm:block">
                        {subtitle}
                      </p>
                    )}
                  </div>
                </div>
              </>
            )}
          </div>

          {/* Right section - Custom content and user actions */}
          <div className="flex items-center space-x-2 flex-shrink-0">
            {rightContent}

            {/* Always show user actions when logged in */}
            {user && (
              <>
                <div className="hidden sm:flex items-center space-x-2 text-sm text-muted-foreground">
                  <User className="h-4 w-4" />
                  <span>{user.email}</span>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={signOut}
                  className="text-muted-foreground hover:text-foreground transition-colors duration-150 min-h-[44px]"
                >
                  <LogOut className="h-4 w-4 sm:mr-2" />
                  <span className="hidden sm:inline">Sign out</span>
                </Button>
              </>
            )}
          </div>
        </div>
      </div>
    </header>
  )
}

